import { Button, Card, Container, Grid, styled, TextField } from "@mui/material";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import HeaderBreadcrumbs from "src/components/HeaderBreadcrumbs";
import Page from "src/components/Page";
// routes
import { PATH_DASHBOARD } from "src/routes/paths";
// hooks
import useSettings from "../../../../../hooks/useSettings";
import { useState } from "react";

import { IconPlus, IconPencil, IconTrash } from "@tabler/icons-react";
import AppleIcon from '@mui/icons-material/Apple';

const columns = [
  { id: "name", label: "Tên", width: 30 },
  { id: "code", label: "Giá trị", width: 250 },
  { id: "action", label: "Hành động", width: 40 },
];

export default function BieuDoTranh() {
  const { themeStretch } = useSettings();

  const [inputName, setInputName] = useState("");
  const [inputCode, setInputCode] = useState("");
  const [rows, setRows] = useState([
    {
      name: 'Dữ liệu 1',
      code: 4
    },
    {
      name: 'Dữ liệu 2',
      code: 5
    },
    {
      name: 'Dữ liệu 3',
      code: 7
    },
    {
      name: 'Dữ liệu 4',
      code: 8
    },
    {
      name: 'Dữ liệu 5',
      code: 10
    },
  ]); // rows sẽ chứa dữ liệu bảng
  const [editIndex, setEditIndex] = useState(null); // Lưu index của dòng đang chỉnh sửa

  // Hàm kiểm tra nếu giá trị là số
  const handleCodeChange = (e) => {
    const value = e.target.value;
    if (!isNaN(value) || value === "") { // Chỉ cho phép nhập số
      setInputCode(value);
    }
  };

  // Hàm thêm dữ liệu vào bảng
  const handleAddClick = () => {
    if (inputName && inputCode && !isNaN(inputCode)) {
      const newRow = { name: inputName, code: parseInt(inputCode, 10) };
      setRows([...rows, newRow]);
      setInputName("");
      setInputCode("");
    } else {
      alert("Vui lòng nhập đầy đủ thông tin và đảm bảo giá trị là số!");
    }
  };

  // Hàm chỉnh sửa dữ liệu
  const handleEdit = (index) => {
    const rowToEdit = rows[index];
    setInputName(rowToEdit.name); // Đưa giá trị vào các input
    setInputCode(rowToEdit.code.toString());
    setEditIndex(index); // Lưu index của dòng đang chỉnh sửa
  };

  // Hàm lưu dữ liệu sau khi chỉnh sửa
  const handleSaveEdit = () => {
    if (inputName && inputCode && editIndex !== null && !isNaN(inputCode)) {
      const updatedRows = [...rows];
      updatedRows[editIndex] = { name: inputName, code: parseInt(inputCode, 10) };
      setRows(updatedRows);
      setInputName("");
      setInputCode("");
      setEditIndex(null); // Reset lại chỉ số dòng đang chỉnh sửa
    } else {
      alert("Vui lòng nhập đầy đủ thông tin và đảm bảo giá trị là số!");
    }
  };

  // Hàm xóa dữ liệu
  const handleDelete = (index) => {
    const newRows = rows.filter((_, i) => i !== index); // Xóa dòng theo index
    setRows(newRows);
  };

  return (
    <Page title="Biểu đồ Tranh">
      <Container maxWidth={themeStretch ? false : "lg"}>
        <HeaderBreadcrumbs
          heading="Biểu đồ Tranh"
          links={[
            { name: "Thống kê và Xác suất", href: PATH_DASHBOARD.thongKeVaXacSuat.root },
            { name: "Biểu đồ", href: PATH_DASHBOARD.thongKeVaXacSuat.bieuDo.root },
            { name: "Biểu đồ Tranh" },
          ]}
        />
        <Card>
          <Grid container spacing={3} alignItems="center" justifyContent="space-between" sx={{ mb: 2 }}>
            {/* Input Name */}
            <Grid item xs={12} sm={5} sx={{ mt: 2 }}>
              <TextField
                label="Tiêu đề"
                fullWidth
                value={inputName}
                onChange={(e) => setInputName(e.target.value)}
                variant="outlined"
                placeholder="Nhập tiêu đề"
              />
            </Grid>
            {/* Input Code */}
            <Grid item xs={12} sm={5} sx={{ mt: 2 }}>
              <TextField
                label="Giá trị"
                fullWidth
                value={inputCode}
                onChange={handleCodeChange} // Sử dụng handleCodeChange để kiểm tra nhập liệu
                variant="outlined"
                placeholder="Nhập số"
              />
            </Grid>
            <Grid item sm={2} sx={{ mt: 2 }}>
              {editIndex === null ? (
                <Button variant="contained" color="success" onClick={handleAddClick}>
                  <IconPlus />
                </Button>
              ) : (
                <Button variant="contained" color="primary" onClick={handleSaveEdit}>
                  Lưu
                </Button>
              )}
            </Grid>
          </Grid>
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Table stickyHeader>
                <TableHead>
                  <TableRow>
                    {columns.map((column) => (
                      <TableCell key={column.id} align={column.align} style={{ width: column.width }}>
                        {column.label}
                      </TableCell>
                    ))}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {rows.map((row, index) => (
                    <TableRow hover key={index}>
                      <TableCell>{row.name}</TableCell>
                      <TableCell>
                        {/* Hiển thị số lượng icon Apple tương ứng với row.code */}
                        {Array.from({ length: row.code }).map((_, i) => (
                          <AppleIcon key={i} sx={{ color: '#ff6d75' }} />
                        ))}
                      </TableCell>
                      <TableCell>
                        <Button variant="contained" color="secondary" onClick={() => handleEdit(index)} sx={{ marginRight: 1 }}>
                          <IconPencil />
                        </Button>
                        <Button variant="contained" color="error" onClick={() => handleDelete(index)}>
                          <IconTrash />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </Grid>
          </Grid>
        </Card>
      </Container>
    </Page>
  );
}
